mapper.select:
select user_id, username, name, email, mobile, status, gmt_create, gmt_modified
from sys_user
where user_id = #{userId}

select count(*) from sys_user
where username = #{username}

    and user_id != #{excludeId}

select role_id, role_name, role_sign, remark, gmt_create, gmt_modified
from sys_role
where role_id = #{roleId}

select count(*) from sys_role
where role_sign = #{roleSign}

    and role_id != #{excludeId}

select menu_id, parent_id, name, url, perms, type, icon, order_num, gmt_create, gmt_modified
from sys_menu
where menu_id = #{menuId}
